import { useTranslation } from "react-i18next";
import { formatDateForDisplay } from "@/lib/utils/datetime";

interface AccountActivityProps {
  createdAt: Date;
  lastLoginAt: Date | null;
  locale: string;
}

export const AccountActivity = ({ createdAt, lastLoginAt, locale }: Readonly<AccountActivityProps>) => {
  const { t } = useTranslation();

  return (
    <div>
      <div className="mb-4 flex items-center gap-2">
        <span className="font-regular text-xs text-slate-700">{t("workspace.settings.profile.account_created")}:</span>
        <span className="text-sm text-slate-900">{formatDateForDisplay(createdAt, locale)}</span>
      </div>
      <div className="flex items-center gap-2">
        <span className="font-regular text-xs text-slate-700">{t("workspace.settings.profile.last_login")}:</span>
        <span className="text-sm text-slate-900">
          {lastLoginAt ? formatDateForDisplay(lastLoginAt, locale) : t("common.not_set")}
        </span>
      </div>
    </div>
  );
};

"use client";

import { useState, useTransition } from "react";
import { useTranslation } from "react-i18next";
import { downloadMyDataAction } from "../actions";
import { Button } from "@/modules/ui/components/button";

export const DownloadMyData = () => {
  const { t } = useTranslation();
  const [isPending, startTransition] = useTransition();

  const handleDownload = () => {
    startTransition(async () => {
      const result = await downloadMyDataAction();

      if (result.error || !result.data) {
        return;
      }

      const { name, email, locale, notificationSettings, organizationMemberships } = result.data;

      const data = {
        name,
        email,
        locale,
        notificationSettings,
        organizationMemberships,
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "formbricks-data.json";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    });
  };

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload} disabled={isPending}>
      {isPending ? t("workspace.settings.profile.downloading") : t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};

"use server";

import { authenticatedActionClient } from "@/lib/utils/action-client";
import { getSession } from "@/modules/auth/lib/session";
import { getUser } from "@/lib/user/service";
import { lookupAuthorizedOrganizationIds } from "@/lib/authzed/organization-membership";
import { prisma } from "@formbricks/database";

interface OrganizationMembership {
  organizationName: string;
  role: string;
}

interface DownloadMyDataResult {
  name: string;
  email: string;
  locale: string;
  notificationSettings: Record<string, unknown>;
  organizationMemberships: OrganizationMembership[];
}

const ZDownloadMyDataInput = {} as const;

export const downloadMyDataAction = authenticatedActionClient
  .inputSchema(ZDownloadMyDataInput)
  .action(async () => {
    const session = await getSession();
    if (!session?.user) {
      return { error: "Not authenticated" };
    }

    const user = await getUser(session.user.id);
    if (!user) {
      return { error: "User not found" };
    }

    const organizationIds = await lookupAuthorizedOrganizationIds({
      type: "user",
      id: session.user.id,
    });

    const memberships: OrganizationMembership[] = [];

    if (organizationIds.length > 0) {
      const organizations = await prisma.organization.findMany({
        where: {
          id: { in: organizationIds },
        },
        select: {
          id: true,
          name: true,
        },
      });

      const orgMap = new Map(organizations.map((org) => [org.id, org.name]));

      const membershipsRaw = await prisma.membership.findMany({
        where: {
          userId: session.user.id,
          organizationId: { in: organizationIds },
        },
        select: {
          organizationId: true,
          role: true,
        },
      });

      for (const m of membershipsRaw) {
        memberships.push({
          organizationName: orgMap.get(m.organizationId) ?? "",
          role: m.role,
        });
      }
    }

    const data: DownloadMyDataResult = {
      name: user.name,
      email: user.email,
      locale: user.locale,
      notificationSettings: user.notificationSettings,
      organizationMemberships: memberships,
    };

    return { data };
  });

